mem=json.load(open('history/candidates/reference_profile/LawBench/memory.json'))
answers=[e['a'] for e in mem['examples']]
# co-occurrence under ';' split
pairs=collections.Counter()
for a in answers:
    parts=[p.strip() for p in a.split(';') if p.strip()]
    for i,x in enumerate(parts):
        for y in parts[i+1:]:
            pairs[frozenset((x,y))]+=1
comp=collections.defaultdict(collections.Counter)
for pr,c in pairs.items():
    x,y=tuple(pr)
    comp[x][y]+=c; comp[y][x]+=c
rows=[json.loads(l) for l in open('history/results/samples.jsonl')]
