        else: miss+=1
    wrong_sugg += len([s for s in sugg if s not in g])
print('missing labels suggested by co-occurrence>=2:',hit,'missed:',miss)
print('avg spurious suggestions per wrong sample:',round(wrong_sugg/ (len(rp)-49),2))
