def _is_piece_of(part: str, label: str) -> bool:
    """True when ``part`` occurs inside ``label`` on unit boundaries.

    The boundary test keeps a short answer that merely spells part of a longer
    word (a substring of a label in a spaced language) from being reported as a
    truncated label.
    """
    if not part or part == label or len(part) >= len(label):
        return False
    return re.search(rf"(?<!\w){re.escape(part)}(?!\w)", label) is not None

